#!/usr/bin/env python3
"""Offline tests of actual Aladhan responses, not values generated by our formulas."""
import json
import subprocess
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
data = json.loads((ROOT / 'tests/prayer_crosscheck_world.json').read_text(encoding='utf-8'))
rows = data['rows']
assert len(rows) == 60 and {r['method'] for r in rows} >= {1, 2, 3, 11, 12, 13, 14, 15, 17, 20}
assert any(r['name_en'] == 'London' and r['date'] == '21-06-2026' for r in rows)
assert any(r['name_en'] == 'Oslo' and r['date'] == '21-06-2026' for r in rows)
assert all(r['meta']['method']['id'] == r['method'] and r['meta']['latitudeAdjustmentMethod'] == ('NONE' if r['method'] == 15 else 'ANGLE_BASED') for r in rows)
print('PASS 60 independent published responses cover all ten new methods and June high latitudes')
with tempfile.TemporaryDirectory() as tmp:
    tmp = Path(tmp)
    lines = []
    for r in rows:
        lines.append('\t'.join(map(str, [r['name_en'], r['lat'], r['lon'], r['tz'], r['date'], r['method']] +
                    [r['timings'][key] for key in ('Fajr', 'Sunrise', 'Dhuhr', 'Asr', 'Maghrib', 'Isha')])))
    (tmp / 'published.tsv').write_text('\n'.join(lines) + '\n', encoding='utf-8')
    src = ROOT / 'android/launcher/src/main/java/sa/urtv/home/tilawah/PrayerMath.java'
    subprocess.run(['javac', '-encoding', 'UTF-8', '-d', str(tmp), str(src), str(ROOT / 'tests/PrayerWorldRun.java')], check=True)
    cities = json.loads((ROOT / '.github/tools/cities-world/cities-merged.json').read_text(encoding='utf-8'))
    polar = next(r for r in cities if r['name_en'] == 'Longyearbyen')
    subprocess.run(['java', '-Dfile.encoding=UTF-8', '-cp', str(tmp), 'sa.urtv.home.tilawah.PrayerWorldRun', str(tmp / 'published.tsv'), str(polar['lat']), str(polar['lon']), polar['tz']], check=True)
